"""Append reviewed, versioned rules to prior supplement without changing earlier IDs."""
import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[2]))  # scripts/ on the import path
from ordinances.rules.national_rules import *
def build():
 m=j(M);out=j(R/'data/national_rules_astra.json');old={r['id']:r for r in out}
 def add(id,k,state,jurisdiction,level,geoid,topic,summary,locator,evidence,page=None,scope='data center specific',**extra):
  r=dict(id=id,state=state,jurisdiction=jurisdiction,level=level,topic=topic,scope=scope,summary=summary,status='adopted',locator=locator,url=m[k]['url'],authority=extra.pop('authority',jurisdiction),evidence=evidence,**extra)
  if geoid:r['geoid']=geoid
  if page:r['source_page']=page
  if id not in old:out.append(r)
  elif old[id]!=r:raise ValueError('Existing ID would change: '+id)
 def wv(id,k,topic,summary,loc,ev,page=None):add('wv-hidc-'+id,k,'WV','West Virginia','state','54',topic,summary,loc,ev,page)
 wv('definition','wv_definition','definition','A facility or group must meet all statutory tests, including equipment use and common or affiliated ownership, operation or leasing; aggregate critical IT load of at least 90 MW; and in-service date on or after July 1, 2025. Critical IT load is distinct from total campus electricity demand.','W.Va. Code §11-6N-2(b)(4), (6)(A)–(E)','90 megawatts total or higher')
 wv('local-preemption','wv_preempt','use permission','State law preempts county and municipal zoning, noise, viewshed, lighting, development or land-use restrictions and approvals for certified microgrid districts and certified high-impact data centers. Do not apply this to an uncertified facility based on size alone.','W.Va. Code §5B-2-21B(c)–(d)(1)','zoning, horticultural, noise, viewshed, lighting, development, or land use ordinances')
 wv('local-building','wv_preempt','building permit','Certified projects are also excluded from county or municipal building permitting, inspection, code enforcement and local license requirements under the cited statute. This does not establish an exemption from state or federal environmental requirements.','W.Va. Code §5B-2-21B(d)(2)–(3)','County or municipal building permitting, inspection, or code enforcement')
 wv('application','wv_145','state certification','A qualifying petitioner must apply to the Secretary within 30 days after learning it will meet, or after satisfying, the statutory definition. The petition must give proposed critical IT and total load; the rule also requests proposed acreage, location, utility power-study information and project milestones.','145 CSR 20 §§10.1–10.1.3; effective April 1, 2026','proposed critical IT load and total load',6)
 def ky(id,topic,summary,loc,ev):add('ky-louisville-'+id,'ky_ordinance','KY','Louisville/Jefferson County Metro Government','regional',None,topic,summary,'O-135-26, Ord. 151, Series 2026, '+loc,ev,authority='Louisville Metro Council')
 ky('file-pause','moratorium','Metro suspended acceptance and further processing by its named planning and zoning bodies of rezoning, conditional-use and Plan Certain Category 2B/3 applications proposing telecommunications hotels or data centers. The term is 180 days from effectiveness unless repealed, extended or Council takes final action on proposed LDC changes. This is not imputed as a separate enactment by every suburban city.','§§I, III','one hundred eighty (180) calendar days')
 ky('hearing-exception','grandfathering','Applications already scheduled for a public hearing on the effective date may continue to be processed and decided by the planning and zoning bodies. Earlier filing alone is not the stated test.','§I','scheduled for a public hearing as of the effective date')
 ky('reuse','building permit','Metro staff must pause building-permit applications for repurposing an existing structure as a telecommunications hotel or data center under the ordinance. This is a specific building-permit provision in addition to the listed land-use application types.','§II','repurposing of an existing structure for telecommunications hotels')
 add('ks-desoto-m1','ks_desoto','KS','De Soto','city','2017850','use permission','The city interprets its M-1 Light Industrial district as permitting data centers. A proposed use must still satisfy site-plan, utility, building and other applicable requirements; permitted-use status is not authorization to break ground.','City data-center zoning explanation, “Why are data centers allowed in De Soto?”','M-1 (Light Industrial), which allows data centers as a permitted use',source_type='government interpretation of existing zoning')
 add('ks-sedgwick-extension','ks_county_sept','KS','Sedgwick County','county','20173','moratorium','The board extended interim development control to December 24, 2026. The original county measure concerns data-center land-use and building applications in unincorporated Sedgwick County. It does not enact Wichita city limits as a separate coverage area.','September 2, 2026 board actions; Res. 014-2026 as extended; earlier Res. 095-2026 §§1–3','extension of the Data Centers Interim Development Control to Dec. 24, 2026',related_url=m['ks_sedgwick']['url'])
 def ok(id,k,topic,summary,loc,ev,pg):add('ok-tulsa-'+id,k,'OK','Tulsa','city','4075000',topic,summary,loc,ev,pg)
 ok('classification','tulsa_report','definition','The 2024 zoning amendment classified data centers as Low-impact Manufacturing and Industry. The later March 2026 moratorium temporarily affects new data centers despite that classification. Proposed ZCA-41 standards are not treated as adopted here.','November 4 planning packet, PDF p. 3; ZCA-31 / §35.070-A.4','classified as a Low-impact Manufacturing and Industry use',3)
 ok('tower','tulsa_code','accessory use','An accessory data-center tower may not exceed 100 feet or lie within 200 feet of the property boundary unless the Board of Adjustment allows greater height or a different location by special exception.','Tulsa Zoning Code §40.420-E.2.c, ZCA-31','shall not be located within 200 feet of the property boundary',171)
 ok('parking','tulsa_code','parking','Minimum parking depends on floor use: one space per 1,000 square feet of office, and 0.15 space per 1,000 square feet of warehouse, storage or technology-equipment area.','Tulsa Zoning Code §55.050-M, ZCA-31','0.15 space per 1,000 square feet',210)
 ok('pause','tulsa_report','moratorium','City planning staff report the Council declared a March 25, 2026 moratorium on new data centers through December 31, 2026. This records the adopted pause, not a future extension or a permanent change to the use table.','November 4 planning packet, PDF p. 3, background on Council action','moratorium on new data centers, effective through December 31, 2026',3)
 def nm(id,topic,summary,loc,ev,pg):add('nm-santafe-'+id,'nm_santafe','NM','Santa Fe County','county','35049',topic,summary,'Recorded Ordinance 2026-06 '+loc,ev,pg,related_url=m['nm_scope']['url'],evidence_method='OCR checked against the recorded ordinance; exhibit has no embedded text.',effective_date='2026-07-09')
 nm('scope','definition','Santa Fe County defines a qualifying facility or proposed expansion by primary computing use and proposed aggregate IT load capacity of at least 1 MW. It excludes incidental computer rooms serving another lawful principal use when separate high-capacity infrastructure is unnecessary.','§2(D)–(E), PDF pp. 1–2','ordinary computer rooms, server closets, telecommunications rooms',1)
 nm('moratorium','moratorium','County acceptance, processing and issuance of new development approvals and permits for covered data centers are paused for 18 months from recordation, subject to exceptions and the Board’s extension power. County adoption was June 30, 2026; recordation was July 9.','§§5, 10, PDF pp. 4 and 6','No Development Approval or Development Permit for a Data Center shall be issued',4)
 nm('exempt','grandfathering','Exceptions include county-owned or county-operated facilities used solely for governmental data processing and facilities for which the county accepted a complete development approval or permit application before effectiveness. Separate vested-rights determinations may be appealed.','§§4(B)–(C), 6, PDF pp. 4–5','County-owned or County-operated facilities used solely for governmental data processing purposes',4)
 add('az-srpmic-conditional','srpmic','AZ','Salt River Pima-Maricopa Indian Community','tribal',None,'conditional use','Where the Community’s use table requires a conditional use permit, Community Council approval is required. Applicable landowner consents are required unless the applicant holds written authorization. The Council considers compatibility and infrastructure. No data-center use is assigned to a district by this general provision.','Community Zoning Ordinance, SRO-467-2015, §§2.8.1–2.8.3, PDF p. 21','applicable consents from the landowners',21,'generally applicable',related_url=m['srpmic_current']['url'])
 add('mp-saipan-conditional','mp_art7','MP','Saipan Municipality','county','69110','conditional use','The Saipan law applies conditional review to uses designated by §404; the Board may identify others. Applicants must show compatibility and adequate public facilities, including roads, drainage, potable water and sanitary sewer. This general rule concerns Saipan only and does not classify data centers.','Saipan Zoning Law, Art. 7 §§701(b), 702, PDF p. 1','Be compatible with the existing or allowable uses of adjacent properties',1,'generally applicable',authority='Commonwealth Zoning Board / Saipan land-use law',related_url=m['mp_publication']['url'])
 collect.dump(R/'data/national_rules_astra.json',out);return len(out)
if __name__=='__main__':print(build());validate()
